// Shared bits of the invite flow: the short link, the cookie that carries a
// code from the invite page to the member's first visit, and code validation.
export const INVITE_COOKIE = "rr_invite";
export const INVITE_COOKIE_DAYS = 30;

// 10 hex characters, as generated by migration 0024.
export const isInviteCode = (value: unknown): value is string =>
  typeof value === "string" && /^[0-9a-f]{10}$/i.test(value);

export function inviteUrl(origin: string, code: string) {
  return `${origin.replace(/\/$/, "")}/i/${code}`;
}
